// Package speccheck compares the Terrakube Go client against the Terrakube
// OpenAPI document: it discovers the client's services and models by
// reflection, maps Go types to OpenAPI types, and reports fields, types, and
// paths that do not match.
//
// The Terrakube API is generated by Elide. Its OpenAPI document describes each
// JSON:API resource type as a schema whose "attributes" and "relationships"
// properties list the resource's fields. Every relationship is rendered with an
// array "data" member, so cardinality is taken from the paths, not the schema.
package speccheck

import (
	"cmp"
	"fmt"
	"regexp"
	"slices"
	"strings"

	"github.com/getkin/kin-openapi/openapi3"
)

// Spec is a loaded OpenAPI document with helpers for Elide JSON:API schemas.
type Spec struct {
	doc *openapi3.T
}

// Property describes one attribute of a resource schema.
type Property struct {
	Type      string // OpenAPI type: string, boolean, integer, number, array, object
	Format    string // OpenAPI format, e.g. int32
	ItemsType string // for arrays: the type of the items
}

// String renders the property as "type" or "type/format".
func (p Property) String() string {
	if p.Format != "" {
		return p.Type + "/" + p.Format
	}
	return p.Type
}

// Relation describes one relationship of a resource schema.
type Relation struct {
	Target string // JSON:API type of the related resource
}

// Resource is the attribute and relationship view of one resource schema.
type Resource struct {
	Type       string
	Attributes map[string]Property
	Relations  map[string]Relation
}

// LoadFile reads an OpenAPI document (JSON or YAML) from path.
func LoadFile(path string) (*Spec, error) {
	doc, err := openapi3.NewLoader().LoadFromFile(path)
	if err != nil {
		return nil, fmt.Errorf("loading OpenAPI document %s: %w", path, err)
	}
	return &Spec{doc: doc}, nil
}

// LoadData parses an OpenAPI document (JSON or YAML) from memory.
func LoadData(data []byte) (*Spec, error) {
	doc, err := openapi3.NewLoader().LoadFromData(data)
	if err != nil {
		return nil, fmt.Errorf("parsing OpenAPI document: %w", err)
	}
	return &Spec{doc: doc}, nil
}

// Doc returns the underlying document.
func (s *Spec) Doc() *openapi3.T { return s.doc }

// ResourceTypes returns the JSON:API types described by the document, sorted.
func (s *Spec) ResourceTypes() []string {
	var types []string
	if s.doc.Components == nil {
		return nil
	}
	for name, ref := range s.doc.Components.Schemas {
		if ref == nil || ref.Value == nil {
			continue
		}
		if _, ok := ref.Value.Properties["attributes"]; ok {
			types = append(types, name)
			continue
		}
		if _, ok := ref.Value.Properties["relationships"]; ok {
			types = append(types, name)
		}
	}
	slices.Sort(types)
	return types
}

// Resource returns the attributes and relationships of the resource type typ.
func (s *Spec) Resource(typ string) (*Resource, bool) {
	if s.doc.Components == nil {
		return nil, false
	}
	ref, ok := s.doc.Components.Schemas[typ]
	if !ok || ref == nil || ref.Value == nil {
		return nil, false
	}
	res := &Resource{Type: typ, Attributes: map[string]Property{}, Relations: map[string]Relation{}}
	if attrs := ref.Value.Properties["attributes"]; attrs != nil && attrs.Value != nil {
		for name, p := range attrs.Value.Properties {
			if p == nil || p.Value == nil {
				continue
			}
			res.Attributes[name] = propertyOf(p.Value)
		}
	}
	if rels := ref.Value.Properties["relationships"]; rels != nil && rels.Value != nil {
		for name, r := range rels.Value.Properties {
			res.Relations[name] = Relation{Target: relationTarget(r)}
		}
	}
	return res, true
}

func propertyOf(s *openapi3.Schema) Property {
	p := Property{Type: firstType(s.Type), Format: s.Format}
	if p.Type == "array" && s.Items != nil && s.Items.Value != nil {
		p.ItemsType = firstType(s.Items.Value.Type)
	}
	return p
}

func firstType(t *openapi3.Types) string {
	if t == nil || len(*t) == 0 {
		return ""
	}
	return (*t)[0]
}

// relationTarget reads the related type from data.items.properties.type.enum
// (Elide) or data.properties.type.enum (to-one in hand-written documents).
func relationTarget(r *openapi3.SchemaRef) string {
	if r == nil || r.Value == nil {
		return ""
	}
	data := r.Value.Properties["data"]
	if data == nil || data.Value == nil {
		return ""
	}
	item := data.Value
	if item.Items != nil && item.Items.Value != nil {
		item = item.Items.Value
	}
	typ := item.Properties["type"]
	if typ == nil || typ.Value == nil || len(typ.Value.Enum) == 0 {
		return ""
	}
	name, _ := typ.Value.Enum[0].(string)
	return name
}

// Paths returns every path template in the document, sorted.
func (s *Spec) Paths() []string {
	if s.doc.Paths == nil {
		return nil
	}
	paths := make([]string, 0, s.doc.Paths.Len())
	for p := range s.doc.Paths.Map() {
		paths = append(paths, p)
	}
	slices.Sort(paths)
	return paths
}

// Operations returns the HTTP methods (upper case) defined on a path template.
func (s *Spec) Operations(path string) []string {
	item := s.pathItem(path)
	if item == nil {
		return nil
	}
	var ops []string
	for m := range item.Operations() {
		ops = append(ops, strings.ToUpper(m))
	}
	slices.Sort(ops)
	return ops
}

func (s *Spec) pathItem(path string) *openapi3.PathItem {
	if s.doc.Paths == nil {
		return nil
	}
	return s.doc.Paths.Value(path)
}

// PathResource reports which resource type a GET on path returns and whether
// it returns a collection (an array "data" member).
func (s *Spec) PathResource(path string) (typ string, collection bool, ok bool) {
	item := s.pathItem(path)
	if item == nil || item.Get == nil || item.Get.Responses == nil {
		return "", false, false
	}
	resp := item.Get.Responses.Status(200)
	if resp == nil || resp.Value == nil {
		return "", false, false
	}
	for _, media := range resp.Value.Content {
		if media.Schema == nil || media.Schema.Value == nil {
			continue
		}
		data := media.Schema.Value.Properties["data"]
		if data == nil {
			continue
		}
		if data.Value != nil && data.Value.Items != nil {
			return refName(data.Value.Items.Ref), true, true
		}
		return refName(data.Ref), false, true
	}
	return "", false, false
}

func refName(ref string) string {
	_, name, _ := strings.Cut(ref, "#/components/schemas/")
	return name
}

var paramSegment = regexp.MustCompile(`^\{[^}]+\}$`)

// MatchPath finds the path template that a concrete request path (relative to
// the API base, e.g. /organization/x0/workspace) corresponds to. A template
// segment in braces matches any concrete segment; other segments must be equal.
func (s *Spec) MatchPath(concrete string) (string, bool) {
	want := splitPath(concrete)
	var matches []string
	for _, tmpl := range s.Paths() {
		segs := splitPath(tmpl)
		if len(segs) != len(want) {
			continue
		}
		if segmentsMatch(segs, want) {
			matches = append(matches, tmpl)
		}
	}
	if len(matches) == 0 {
		return "", false
	}
	// Prefer the template with the most literal segments.
	slices.SortStableFunc(matches, func(a, b string) int {
		return cmp.Compare(paramCount(a), paramCount(b))
	})
	return matches[0], true
}

func segmentsMatch(tmpl, concrete []string) bool {
	for i, seg := range tmpl {
		if paramSegment.MatchString(seg) {
			continue
		}
		if seg != concrete[i] {
			return false
		}
	}
	return true
}

func paramCount(tmpl string) int {
	n := 0
	for _, seg := range splitPath(tmpl) {
		if paramSegment.MatchString(seg) {
			n++
		}
	}
	return n
}

func splitPath(p string) []string {
	return strings.Split(strings.Trim(p, "/"), "/")
}

// ResolvePath reports which resource type a concrete request path (relative
// to the API base) addresses and whether it addresses a collection. A path
// listed in the document is resolved from its GET response. Elide lists only
// some nested paths but serves every relationship chain, so other paths are
// resolved hop by hop: the first segment must be a root collection, and each
// following name must be a relationship of the type reached so far. via is
// "path" or "relationships".
func (s *Spec) ResolvePath(concrete string) (typ string, collection bool, via string, ok bool) {
	if tmpl, found := s.MatchPath(concrete); found {
		if typ, collection, ok := s.PathResource(tmpl); ok {
			// A documented nested collection may still be a to-one
			// relationship: take the cardinality from its relationship endpoint.
			if segs := splitPath(tmpl); collection && len(segs) >= 3 && paramSegment.MatchString(segs[len(segs)-2]) {
				owner, _, okOwner := s.PathResource("/" + strings.Join(segs[:len(segs)-1], "/"))
				if okOwner {
					if toMany, known := s.RelationIsToMany(owner, segs[len(segs)-1]); known {
						collection = toMany
					}
				}
			}
			return typ, collection, "path", true
		}
	}
	segs := splitPath(concrete)
	typ, collection, ok = s.PathResource("/" + segs[0])
	if !ok || !collection {
		return "", false, "", false
	}
	for i := 1; i < len(segs); i++ {
		if i%2 == 1 { // an ID selects one item of the current type
			collection = false
			continue
		}
		res, found := s.Resource(typ)
		if !found {
			return "", false, "", false
		}
		rel, found := res.Relations[segs[i]]
		if !found || rel.Target == "" {
			return "", false, "", false
		}
		toMany, known := s.RelationIsToMany(typ, segs[i])
		typ, collection = rel.Target, toMany || !known
	}
	return typ, collection, "relationships", true
}

// CollectionPaths returns the non-relationship collection path templates
// whose GET returns a collection of typ, shortest first.
func (s *Spec) CollectionPaths(typ string) []string {
	var out []string
	for _, p := range s.Paths() {
		if strings.Contains(p, "/relationships/") || strings.HasSuffix(p, "}") {
			continue
		}
		got, collection, ok := s.PathResource(p)
		if ok && collection && got == typ {
			out = append(out, p)
		}
	}
	slices.SortStableFunc(out, func(a, b string) int {
		return cmp.Or(cmp.Compare(len(splitPath(a)), len(splitPath(b))), cmp.Compare(a, b))
	})
	return out
}

// RelationIsToMany reports whether the relationship rel of resource type
// owner is to-many. Elide renders every relationship "data" as an array, both
// in the schemas and on the nested GET .../{ownerId}/{rel}, so the only
// reliable signal is the relationship endpoint .../{ownerId}/relationships/{rel},
// whose GET returns an object for to-one and an array for to-many. ok is
// false when the document has no such endpoint.
func (s *Spec) RelationIsToMany(owner, rel string) (toMany bool, ok bool) {
	for _, p := range s.Paths() {
		segs := splitPath(p)
		n := len(segs)
		if n < 4 || segs[n-1] != rel || segs[n-2] != "relationships" || !paramSegment.MatchString(segs[n-3]) {
			continue
		}
		parentType, _, okParent := s.PathResource("/" + strings.Join(segs[:n-2], "/"))
		if !okParent || parentType != owner {
			continue
		}
		if isArray, okData := s.dataIsArray(p); okData {
			return isArray, true
		}
	}
	return false, false
}

// dataIsArray reports whether the GET 200 response of path has an array
// "data" member.
func (s *Spec) dataIsArray(path string) (isArray bool, ok bool) {
	item := s.pathItem(path)
	if item == nil || item.Get == nil || item.Get.Responses == nil {
		return false, false
	}
	resp := item.Get.Responses.Status(200)
	if resp == nil || resp.Value == nil {
		return false, false
	}
	for _, media := range resp.Value.Content {
		if media.Schema == nil || media.Schema.Value == nil {
			continue
		}
		data := media.Schema.Value.Properties["data"]
		if data == nil || data.Value == nil {
			continue
		}
		return firstType(data.Value.Type) == "array", true
	}
	return false, false
}
